def page(path,title,desc,content,prefix='',schema=None):
 url=DOMAIN+'/'+path
 data='' if schema is None else '<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</','<\\/')+'</script>'
 out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f4e4e9"><title>{html.escape(title)} | Embryly</title><meta name="description" content="{html.escape(desc,quote=True)}"><meta name="robots" content="noindex,nofollow"><link rel="canonical" href="{url}"><meta property="og:type" content="{'article' if schema else 'website'}"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{DOMAIN}/assets/social-preview.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}assets/site.css?v=20260926-portraits">{data}<script defer src="{prefix}assets/site.js?v=20260926-portraits"></script></head><body>{header(prefix)}<main id="main">{content}</main>{footer(prefix)}</body></html>'''
 (ROOT/path).write_text(out)
