page('blog/index.html','The Embryly journal','Practical, sourced guides to food safety and flexible meal planning during pregnancy.','<div class="wrap subhero"><span class="eyebrow">THE EMBRYLY JOURNAL</span><h1>Good reads.<br><em>For real life.</em></h1><p>A thoughtful place to start with pregnancy, food, and the everyday decisions in between.</p></div><section class="wrap" style="padding-bottom:100px">'+cards('../')+'<p class="tiny-note">Educational articles by the Embryly Editorial Team. Not individual medical advice. Sources and limitations appear in each article.</p></section>',prefix='../')
contact='''<div class="wrap subhero"><span class="eyebrow">LET’S TALK</span><h1>What’s on<br><em>your mind?</em></h1><p>Questions about the app, a privacy request, or something we could do better? We’re listening.</p></div><div class="wrap contact-grid"><div><h2>A note to Embryly.</h2><p><a class="text-link" href="mailto:info@benekan.com">info@benekan.com ↗</a></p><p>For access, correction, export, or permanent erasure requests, choose “Privacy request” and use the email associated with your account.</p><p>Please don’t send pregnancy records, medical documents, passwords, or payment details through this form. Support is not monitored for emergencies and cannot give medical advice.</p><p>Benekan Technologies LLC<br>United States</p></div><form class="contact-form" id="contact-form"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="100"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254"><label for="topic">How can we help?</label><select id="topic" name="topic"><option>App question</option><option>App availability</option><option>Privacy request</option><option>Report incorrect content</option><option>Something else</option></select><label for="message">Your message</label><textarea id="message" name="message" required maxlength="3000" placeholder="Tell us a little about what you need."></textarea><p class="form-note">This opens your email app. Nothing is submitted until you send the email. Read our <a href="privacy-policy.html">privacy policy</a>.</p><button class="button" type="submit">Prepare email <span aria-hidden="true">↗</span></button><p class="form-status" id="form-status" role="status"></p></form></div>'''
page('contact.html','Contact us','Contact Embryly for support, content corrections, privacy requests, and app availability.',contact)
